!> Constructs a modified Givens plane rotation.
!
!! ## Notes
!!
!! * Modified version of reference BLAS level1 routine (version 3.7.0). Updated to "free form" Fortran 95.
!!
!! ## Authors
!!
!! * Univ. of Tennessee
!! * Univ. of California Berkeley
!! * Univ. of Colorado Denver
!! * NAG Ltd.
!!
!! ## License
!!
!! From <http://netlib.org/blas/faq.html>:
!!
!! > The reference BLAS is a freely-available software package. It is available from netlib via anonymous ftp and the World Wide Web. Thus, it can be included in commercial software packages (and has been). We only ask that proper credit be given to the authors.
!! >
!! > Like all software, it is copyrighted. It is not trademarked, but we do ask the following:
!! >
!! > * If you modify the source for these routines we ask that you change the name of the routine and comment the changes made to the original.
!! >
!! > * We will gladly answer any questions regarding the software. If a modification is done, however, it is the responsibility of the person who modified the routine to provide support.
!
! @param {real} dd1 - scaling factor for the first vector component
! @param {real} dd2 - scaling factor for the second vector component
! @param {real} dx1 - first component of the first vector
! @param {real} dy1 - first component of the second vector
! @param {real} dparam - output array (dimension 5)
!<
subroutine drotmg( dd1, dd2, dx1, dy1, dparam )
  implicit none
  ! ..
  ! Internal parameters:
  integer, parameter :: wp = kind(1.d0)
  ! ..
  ! Constants:
  real(wp), parameter :: zero = 0.0d0
  real(wp), parameter :: one  = 1.0d0
  real(wp), parameter :: two  = 2.0d0
  real(wp), parameter :: gam = 4096.0d0
  real(wp), parameter :: gamsq = 16777216.0d0
  real(wp), parameter :: rgamsq = 5.9604645d-8
  ! ..
  ! Scalar Arguments:
  real(wp) :: dd1, dd2, dx1, dy1
  ! ..
  ! Array Arguments:
  real(wp) :: dparam(5)
  ! ..
  ! Local Scalars:
  real(wp) :: dflag, dh11, dh12, dh21, dh22, dp1, dp2, dq1, dq2, dtemp, du
  ! Initialize h variables to zero to avoid uninitialized warnings:
  dh11 = zero
  dh12 = zero
  dh21 = zero
  dh22 = zero
  ! ..
  if ( dd1 .lt. zero ) then
    ! GO ZERO-H-D-AND-DX1..
    dflag = -one
    dh11 = zero
    dh12 = zero
    dh21 = zero
    dh22 = zero

    dd1 = zero
    dd2 = zero
    dx1 = zero
  else
    ! CASE-DD1-NONNEGATIVE
    dp2 = dd2 * dy1
    if ( dp2 .eq. zero ) then
      dflag = -two
      dparam(1) = dflag
      return
    end if
    ! REGULAR-CASE..
    dp1 = dd1 * dx1
    dq2 = dp2 * dy1
    dq1 = dp1 * dx1

    if ( abs(dq1) .gt. abs(dq2) ) then
      dh21 = -dy1 / dx1
      dh12 = dp2 / dp1

      du = one - dh12 * dh21

      if ( du .gt. zero ) then
        dflag = zero
        dd1 = dd1 / du
        dd2 = dd2 / du
        dx1 = dx1 * du
      else
        ! This code path if here for safety. We do not expect this
        ! condition to ever hold except in edge cases with rounding
        ! errors. See DOI: 10.1145/355841.355847
        dflag = -one
        dh11 = zero
        dh12 = zero
        dh21 = zero
        dh22 = zero

        dd1 = zero
        dd2 = zero
        dx1 = zero
      end if
    else
      if ( dq2 .lt. zero ) then
        ! GO ZERO-H-D-AND-DX1..
        dflag = -one
        dh11 = zero
        dh12 = zero
        dh21 = zero
        dh22 = zero

        dd1 = zero
        dd2 = zero
        dx1 = zero
      else
        dflag = one
        dh11 = dp1 / dp2
        dh22 = dx1 / dy1
        du = one + dh11 * dh22
        dtemp = dd2 / du
        dd2 = dd1 / du
        dd1 = dtemp
        dx1 = dy1 * du
      end if
    end if

    ! PROCEDURE..SCALE-CHECK
    if ( dd1 .ne. zero ) then
      do while ( (dd1 .le. rgamsq) .or. (dd1 .ge. gamsq) )
        if ( dflag .eq. zero ) then
          dh11 = one
          dh22 = one
          dflag = -one
        else
          dh21 = -one
          dh12 = one
          dflag = -one
        end if
        if ( dd1 .le. rgamsq ) then
          dd1 = dd1 * gam**2
          dx1 = dx1 / gam
          dh11 = dh11 / gam
          dh12 = dh12 / gam
        else
          dd1 = dd1 / gam**2
          dx1 = dx1 * gam
          dh11 = dh11 * gam
          dh12 = dh12 * gam
        end if
      end do
    end if

    if ( dd2 .ne. zero ) then
      do while ( (abs(dd2) .le. rgamsq) .or. (abs(dd2) .ge. gamsq) )
        if ( dflag .eq. zero ) then
          dh11 = one
          dh22 = one
          dflag = -one
        else
          dh21 = -one
          dh12 = one
          dflag = -one
        end if
        if ( abs(dd2) .le. rgamsq ) then
          dd2 = dd2 * gam**2
          dh21 = dh21 / gam
          dh22 = dh22 / gam
        else
          dd2 = dd2 / gam**2
          dh21 = dh21 * gam
          dh22 = dh22 * gam
        end if
      end do
    end if
  end if

  if ( dflag .lt. zero ) then
    dparam(2) = dh11
    dparam(3) = dh21
    dparam(4) = dh12
    dparam(5) = dh22
  else if ( dflag .eq. zero ) then
    dparam(3) = dh21
    dparam(4) = dh12
  else
    dparam(2) = dh11
    dparam(5) = dh22
  end if

  dparam(1) = dflag
  return
end subroutine drotmg
